WITH eu AS (SELECT e.id AS executivo_id, lower(u.email) = (SELECT valor FROM configuracao WHERE chave = 'admin_email') AS admin FROM INT_USER u LEFT JOIN executivos e ON lower(e.email) = lower(u.email) AND e.ativo WHERE u.user_id = CAST(:VAR_USER AS UUID) AND u.enabled AND lower(u.email) LIKE '%@' || (SELECT valor FROM configuracao WHERE chave = 'dominio')) SELECT q.ordem, q.item->>'pergunta' AS pergunta, q.item->>'objetivo' AS objetivo, q.item->>'dor' AS dor, q.item->>'produto' AS produto FROM pedidos p JOIN eu ON (eu.admin OR p.executivo_id = eu.executivo_id) CROSS JOIN LATERAL jsonb_array_elements(COALESCE(p.perguntas_ia, '[]'::jsonb)) WITH ORDINALITY AS q(item, ordem) WHERE p.pedido_id = :pedido_id ORDER BY q.ordem
